+.you-pet.is-petted .you-pet-emoji { animation: petHop 0.65s ease; }
+
+@keyframes petHop {
+  0%, 100% { transform: translateY(0) rotate(0); }
+  35% { transform: translateY(-9px) rotate(-8deg); }
+  65% { transform: translateY(-3px) rotate(6deg); }
+}
+
+/* ── Kit tabs & pickers ─────────────────────────────────────────── */
+
+.kit-tabs {
+  display: flex;
+  gap: 4px;
+  margin-top: 16px;
+  padding: 4px;
+  border-radius: 999px;
+  border: 1px solid rgba(255, 255, 255, 0.08);
+  background: rgba(0, 0, 0, 0.28);
+  width: fit-content;
+}
+
+.kit-tab {
+  padding: 7px 18px;
+  border: 0;
+  border-radius: 999px;
+  background: none;
+  color: var(--muted);
+  font-family: var(--mono);
+  font-size: 9px;
+  font-weight: 700;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  cursor: pointer;
+  transition: color 0.2s, background 0.2s;
+}
+
+.kit-tab:hover { color: var(--text); }
+.kit-tab.is-active { color: #180a02; background: linear-gradient(180deg, #ff9548, var(--orange)); box-shadow: 0 8px 20px -12px rgba(255, 106, 26, 0.9); }
+
+.kit-hint { padding: 14px 0 4px; font-size: 11.5px; color: var(--muted); }
+
+.kit-grid {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 8px;
+  padding: 10px 0 12px;
+}
+
+.kit-grid-pets { grid-template-columns: repeat(3, 1fr); }
+
+.kit-card {
+  display: flex;
+  flex-direction: column;
+  align-items: flex-start;
+  gap: 4px;
+  padding: 11px 12px;
+  border-radius: 12px;
+  border: 1px solid rgba(255, 255, 255, 0.08);
+  background: rgba(255, 255, 255, 0.025);
+  color: var(--text);
+  cursor: pointer;
+  text-align: left;
+  transition: border-color 0.2s, background 0.2s, transform 0.2s;
+}
+
+.kit-card:hover { border-color: rgba(255, 106, 26, 0.38); background: rgba(255, 106, 26, 0.06); transform: translateY(-1px); }
+
+.kit-card.is-selected {
+  border-color: rgba(255, 106, 26, 0.6);
+  background: linear-gradient(160deg, rgba(255, 106, 26, 0.16), rgba(255, 106, 26, 0.04));
+  box-shadow: inset 0 0 0 1px rgba(255, 106, 26, 0.2);
+}
+
+.kit-card-emoji { font-size: 23px; line-height: 1; }
+.kit-card b { font-size: 11px; font-weight: 650; line-height: 1.2; }
+.kit-card small { font-size: 9px; line-height: 1.35; color: var(--muted); }
+
+.kit-card-check {
+  position: absolute;
+  top: 7px;
+  right: 7px;
+}
+
+.kit-card { position: relative; }
+
+.kit-card .check-dot {
+  display: none;
+  width: 14px;
+  height: 14px;
+  border-radius: 50%;
+  background: var(--orange);
+  color: #180a02;
+  font-size: 9px;
+  font-weight: 800;
+  line-height: 14px;
+  text-align: center;
+}
+
+.kit-card.is-selected .check-dot { display: block; }
+
+.pet-name-row {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  padding: 4px 0 8px;
+}
+
+.pet-name-row span { font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); }
+
+.pet-name-row input {
+  width: 170px;
+  height: 34px;
+  padding: 0 11px;
+  border-radius: 9px;
+  border: 1px solid rgba(255, 255, 255, 0.1);
+  background: rgba(0, 0, 0, 0.28);
+  color: var(--text);
+  font-family: var(--sans);
+  font-size: 12.5px;
+}
+
+.pet-name-row input:focus { outline: none; border-color: rgba(255, 106, 26, 0.6); }
+
+@media (max-width: 700px) {
+  .you-prop { display: none; }
+  .you-pet-emoji { font-size: 22px; }
+  .you-pet-name { font-size: 6px; }
+  .kit-grid, .kit-grid-pets { grid-template-columns: repeat(2, 1fr); }
+  .kit-hint { font-size: 10.5px; }
+}
+
+@media (max-width: 460px) {
+  .you-pet { padding: 0 2px 2px; }
+  .you-pet-name { display: none; }
+}
+
+
+
 @media (max-width: 900px) {
   .park-hud { grid-template-columns: 1fr auto 1fr; gap: 10px; padding: 14px; }
   .hud-team-name { display: none; }
   .hud-score { gap: 10px; padding: 8px 13px; }

