Implementation:
```
const FIXED_STEP = 1 / 60;
const MAX_STEPS = 6;
...
function startLoop() {
  ...
  state.acc = 0;
  const frame = (now) => {
    ...
    const rawDt = (now - (state.last || now)) / 1000;
    const dt = Math.min(rawDt, 0.1);
    state.last = now;

    if (state.running && !state.paused && !game.ended) {
      state.acc = Math.min(state.acc + dt, FIXED_STEP * MAX_STEPS);
      let steps = 0;
      while (state.acc >= FIXED_STEP && steps < MAX_STEPS) {
        updateGame(FIXED_STEP);
        state.acc -= FIXED_STEP;
        steps += 1;
      }
    } else {
      state.acc = 0;
    }
    updateFx(dt);
    render(now/1000);
    ...
  };
}
```
