content.text:
Now loadKit migration. Replace function.

```
function sanitizeProps(list) {
  const ids = Array.isArray(list) ? list : (typeof list === 'string' ? [list] : []);
  const seen = new Set();
  return ids.filter(id => id !== 'none' && PROPS.some(p=>p.id===id) && !seen.has(id) && seen.add(id) !== false).slice(0, MAX_PROPS);
}
```
The `seen.add` trick: `!seen.has(id) && seen.add(id) !== false` returns true. Simpler loop.

```
function sanitizeProps(list) {
  const out = [];
  const source = Array.isArray(list) ? list : (typeof list === 'string' ? [list] : []);
  source.forEach((id) => {
    if (out.length >= MAX_PROPS || out.includes(id)) return;
    if (id !== 'none' && PROPS.some((p) => p.id === id)) out.push(id);
  });
  return out;
}
```
loadKit:
```
function loadKit() {
  let saved = null;
  try {
    saved = JSON.parse(localStorage.getItem(KIT_KEY) || 'null') || JSON.parse(localStorage.getItem(KIT_KEY_LEGACY) || 'null');
  } catch { saved = null; }
  if (saved) {
    const propsSource = Array.isArray(saved.props) ? saved.props : (saved.prop || []);
    return {
      props: sanitizeProps(propsSource),
      pet: PETS.some(p=>p.id===saved.pet) ? saved.pet : DEFAULT_KIT.pet,
      petName: String(saved.petName || DEFAULT_KIT.petName).slice(0,16),
      petColor: /^#[0-9a-f]{6}$/i.test(saved.petColor || '') ? saved.petColor : DEFAULT_KIT.petColor,
    };
  }
  return { ...DEFAULT_KIT, props: [...DEFAULT_KIT.props] };
}
```
Note: If saved props is empty (user chose no props), `Array.isArray` true → []. Good. If legacy `prop:'none'` → sanitize cleans to [].

If saved.petName is '' intentionally (empty input), `saved.petName || DEFAULT` picks default, which we might not want; current behavior does same. Keep but maybe use `typeof saved.petName === 'string' ? saved.petName : default`. Let's preserve empty: `petName: typeof saved.petName === 'string' ? saved.petName.slice(0,16) : DEFAULT_KIT.petName`. applyKit falls back to default for display. Good.

Also saveKit fine.

Add `petFx`/combo/reaction state after kit declaration:
```
const petFx = { hop: 0, bubbleAt: 0 };
const emoteCombo = { count: 0, at: 0 };
const reactions = [];
```

