187:         props: sanitizeProps(Array.isArray(saved.props) ? saved.props : saved.prop),
188:         pet: PETS.some((item) => item.id === saved.pet) ? saved.pet : DEFAULT_KIT.pet,
189:         petName: typeof saved.petName === 'string' ? saved.petName.slice(0, 16) : DEFAULT_KIT.petName,
190:         petColor: /^#[0-9a-f]{6}$/i.test(String(saved.petColor || '')) ? saved.petColor : DEFAULT_KIT.petColor,
