689:   async function runProbe(token) {
690:     const measured = measureRegions();
691:     probe.measured = measured;
692: 
693:     for (let i = 0; i < measured.length; i += 1) {
694:       if (token !== state.loaderToken) return;
695:       revealNode(i, measured[i]);
696:       loaderBar.style.width = `${8 + ((i + 1) / measured.length) * 46}%`;
697:       await sleep(235);
698:     }
699:     if (token !== state.loaderToken) return;
700: 
701:     const best = measured.reduce((lowest, region) => (region.ping <= lowest.ping ? region : lowest));
702:     const scan = probePorts();
703:     best.port = scan.best.port;
704:     best.portRtt = scan.best.rtt;
705:     probe.ports = scan;
706:     probe.best = best;
707:     markBest(best);
708:     loaderTitle.textContent = 'Best connection locked.';
709:     loaderSub.textContent = `${best.name} · ${best.city} — ${best.ping}ms · port ${best.port} wins`;
710:     loaderBar.style.width = '62%';
711:     loaderStep.textContent = `${scan.scanned.length} ports scanned · best handshake ${best.portRtt}ms`;
712:     await sleep(720);
713:     if (token !== state.loaderToken) return;
714: 
715:     loaderTitle.textContent = 'Entering The Park…';
716:     loaderSub.textContent = 'Syncing rosters, court pack, and your sideline kit';
717:     loaderBar.style.width = '93%';
718:     loaderStep.textContent = `Joining ${best.name} · :${best.port} · ${best.ping}ms`;
719:     await sleep(920);
720:     if (token !== state.loaderToken) return;
721: 
722:     loaderBar.style.width = '100%';
723:     await sleep(280);
724:     if (token !== state.loaderToken) return;
725:     enterGame();
726:   }
