884:   const bgCanvas = document.createElement('canvas');
885:   const bgCtx = bgCanvas.getContext('2d');
886: 
887:   function project(x, z) {
888:     const spread = 0.84 + 0.16 * z;
889:     return {
890:       x: view.cx + (x - 0.5) * (view.right - view.left) * spread,
891:       y: view.farY + (view.nearY - view.farY) * z,
892:     };
893:   }
