895:   function resizeCanvas() {
896:     const rect = parkStage.getBoundingClientRect();
897:     const w = Math.max(1, rect.width);
898:     const h = Math.max(1, rect.height);
899:     const dpr = Math.min(window.devicePixelRatio || 1, 2);
900: 
901:     canvas.width = Math.round(w * dpr);
902:     canvas.height = Math.round(h * dpr);
903:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
904:     bgCanvas.width = canvas.width;
905:     bgCanvas.height = canvas.height;
906:     bgCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
907: 
908:     view.w = w;
909:     view.h = h;
910:     view.unit = Math.max(26, Math.min(w * 0.095, h * 0.145));
911:     const portrait = h > w * 1.1;
912:     view.left = w * (portrait ? 0.07 : 0.035);
913:     view.right = w * (portrait ? 0.93 : 0.965);
914:     view.cx = w / 2;
915:     view.farY = h * 0.66;
916:     view.nearY = Math.min(h * 0.945, view.farY + Math.min(h * 0.27, w * 0.46));
917:     view.horizon = view.farY - Math.max(20, view.unit * 0.55);
918: 
919:     buildStars();
920:     buildBuildings();
921:     buildTrees();
922:     buildCrowd();
923:     buildSpecks();
924:     buildBackdrop();
925:   }
926: 
927:   function buildStars() {
928:     view.stars = [];
929:     const count = Math.max(34, Math.round(view.w / 26));
930:     for (let i = 0; i < count; i += 1) {
931:       view.stars.push({
932:         x: rand(0, view.w),
933:         y: rand(0, view.h * 0.42),
934:         r: rand(0.5, 1.5),
935:         a: rand(0.16, 0.75),
936:       });
937:     }
938:   }
939: 
940:   function buildBuildings() {
941:     view.buildings = [];
942:     let x = -view.w * 0.02;
943:     while (x < view.w + 30) {
944:       const width = rand(view.w * 0.025, view.w * 0.085);
945:       const height = rand(view.h * 0.035, view.h * 0.145);
946:       view.buildings.push({
947:         x,
948:         y: view.horizon - height,
949:         w: width,
950:         h: height,
951:         windows: Math.random() > 0.25,
952:         lit: rand(0.25, 0.75),
953:         back: false,
954:       });
955:       x += width + rand(1, view.w * 0.012);
956:     }
957:     // A dimmer second layer for depth.
958:     x = -20;
959:     while (x < view.w + 40) {
960:       const width = rand(view.w * 0.03, view.w * 0.1);
961:       const height = rand(view.h * 0.025, view.h * 0.09);
962:       view.buildings.push({
963:         x,
964:         y: view.horizon - height * 0.72,
965:         w: width,
966:         h: height,
967:         windows: false,
968:         lit: 0.2,
969:         back: true,
970:       });
971:       x += width + rand(4, 24);
972:     }
973:   }
974: 
975:   function buildTrees() {
976:     view.trees = [];
977:     const count = Math.max(4, Math.round(view.w / 210));
978:     for (let i = 0; i < count; i += 1) {
979:       view.trees.push({
980:         x: rand(-20, view.w + 20),
981:         y: view.horizon + rand(0, 10),
982:         r: rand(view.unit * 0.35, view.unit * 0.75),
983:         shade: rand(0.06, 0.14),
984:       });
985:     }
986:   }
987: 
988:   function buildCrowd() {
989:     view.crowd = [];
990:     const count = clamp(Math.round(view.w / 34), 16, 52);
991:     const colors = ['#1a2330', '#222d39', '#2c2533', '#1c2b2c', '#26303a'];
992:     for (let i = 0; i < count; i += 1) {
993:       view.crowd.push({
994:         x: (i + rand(0.1, 0.9)) / count * view.w,
995:         y: view.farY + rand(-2, 7),
996:         h: view.unit * rand(0.3, 0.46),
997:         phase: rand(0, TAU),
998:         color: pick(colors),
999:         accent: pick(['#ff6a1a', '#38e8ff', '#ffb347', '#38ff9c']),
1000:         hasAccent: Math.random() < 0.22,
1001:       });
1002:     }
1003:   }
1004: 
1005:   function buildSpecks() {
1006:     view.specks = [];
1007:     for (let i = 0; i < 110; i += 1) {
1008:       view.specks.push({
1009:         x: rand(0, 1),
1010:         z: rand(0, 1),
1011:         r: rand(0.5, 1.8),
1012:         a: rand(0.03, 0.1),
1013:         warm: Math.random() < 0.4,
1014:       });
1015:     }
1016:   }
1017: 
1018:   function buildBackdrop() {
1019:     const c = bgCtx;
1020:     const w = view.w;
1021:     const h = view.h;
1022:     c.clearRect(0, 0, w, h);
1023: 
1024:     const sky = c.createLinearGradient(0, 0, 0, view.farY + view.unit * 0.6);
1025:     sky.addColorStop(0, '#050711');
1026:     sky.addColorStop(0.32, '#11122a');
1027:     sky.addColorStop(0.55, '#2c1c36');
1028:     sky.addColorStop(0.74, '#5c2c35');
1029:     sky.addColorStop(0.9, '#a84d33');
1030:     sky.addColorStop(1, '#e57a41');
1031:     c.fillStyle = sky;
1032:     c.fillRect(0, 0, w, h);
1033: 
1034:     const sun = c.createRadialGradient(w * 0.72, view.horizon + 8, 0, w * 0.72, view.horizon + 8, w * 0.44);
1035:     sun.addColorStop(0, 'rgba(255, 186, 112, 0.5)');
1036:     sun.addColorStop(0.35, 'rgba(255, 124, 60, 0.18)');
1037:     sun.addColorStop(1, 'rgba(255, 106, 26, 0)');
1038:     c.fillStyle = sun;
1039:     c.fillRect(0, 0, w, view.farY + 30);
1040: 
1041:     // Stars
1042:     for (const star of view.stars) {
1043:       c.globalAlpha = star.a;
1044:       c.fillStyle = '#dfe9ff';
1045:       c.beginPath();
1046:       c.arc(star.x, star.y, star.r, 0, TAU);
1047:       c.fill();
1048:     }
1049:     c.globalAlpha = 1;
1050: 
1051:     // Skyline
1052:     for (const building of view.buildings) {
1053:       c.fillStyle = building.back ? 'rgba(14, 16, 28, 0.6)' : '#0c0f1a';
1054:       c.fillRect(building.x, building.y, building.w, building.h + (view.horizon - building.y));
1055:       if (building.windows) {
1056:         const cols = Math.max(1, Math.floor(building.w / 9));
1057:         const rows = Math.max(1, Math.floor(building.h / 13));
1058:         for (let cx = 0; cx < cols; cx += 1) {
1059:           for (let ry = 0; ry < rows; ry += 1) {
1060:             if (Math.random() > 0.36) continue;
1061:             c.fillStyle = `rgba(255, 190, 110, ${rand(0.12, 0.55) * building.lit})`;
1062:             c.fillRect(
1063:               building.x + 3 + cx * (building.w - 6) / cols,
1064:               building.y + 5 + ry * (building.h - 8) / rows,
1065:               1.6,
1066:               2.4,
1067:             );
1068:           }
1069:         }
1070:       }
1071:     }
1072: 
1073:     // Distant trees
1074:     for (const tree of view.trees) {
1075:       c.fillStyle = `rgba(5, 12, 10, ${0.55 + tree.shade})`;
1076:       c.beginPath();
1077:       c.arc(tree.x, tree.y - tree.r * 0.5, tree.r, 0, TAU);
1078:       c.arc(tree.x + tree.r * 0.55, tree.y - tree.r * 0.22, tree.r * 0.62, 0, TAU);
1079:       c.arc(tree.x - tree.r * 0.55, tree.y - tree.r * 0.2, tree.r * 0.58, 0, TAU);
1080:       c.fill();
1081:       c.fillRect(tree.x - 2, tree.y - tree.r * 0.4, 4, tree.r * 0.8);
1082:     }
1083: 
1084:     // Chain-link fence behind the crowd
1085:     const fenceTop = view.farY - view.unit * 0.9;
1086:     const postGap = Math.max(42, view.unit * 1.1);
1087:     c.strokeStyle = 'rgba(210, 225, 235, 0.10)';
1088:     c.lineWidth = 1;
1089:     for (let x = 0; x < w; x += postGap) {
1090:       c.beginPath();
1091:       c.moveTo(x, fenceTop);
1092:       c.lineTo(x, view.farY + 4);
1093:       c.stroke();
1094:       c.strokeStyle = 'rgba(210, 225, 235, 0.05)';
1095:       c.beginPath();
1096:       c.moveTo(x, fenceTop);
1097:       c.lineTo(x + postGap, view.farY + 4);
1098:       c.moveTo(x + postGap, fenceTop);
1099:       c.lineTo(x, view.farY + 4);
1100:       c.stroke();
1101:       c.strokeStyle = 'rgba(210, 225, 235, 0.10)';
1102:     }
1103:     c.beginPath();
1104:     c.moveTo(0, fenceTop);
1105:     c.lineTo(w, fenceTop);
1106:     c.strokeStyle = 'rgba(255, 255, 255, 0.13)';
1107:     c.lineWidth = 2;
1108:     c.stroke();
1109: 
1110:     // String lights over the court
1111:     const lightPoles = [w * 0.05, w * 0.95];
1112:     c.strokeStyle = 'rgba(8, 10, 15, 0.9)';
1113:     c.lineWidth = Math.max(2, view.unit * 0.025);
1114:     for (const px of lightPoles) {
1115:       c.beginPath();
1116:       c.moveTo(px, view.farY);
1117:       c.lineTo(px, h * 0.13);
1118:       c.stroke();
1119:     }
1120:     for (let wire = 0; wire < 2; wire += 1) {
1121:       const y0 = h * (0.16 + wire * 0.035);
1122:       const sag = h * (0.025 + wire * 0.015);
1123:       c.beginPath();
1124:       c.moveTo(lightPoles[0], y0);
1125:       c.quadraticCurveTo(w / 2, y0 + sag * 2.2, lightPoles[1], y0);
1126:       c.strokeStyle = 'rgba(10, 12, 18, 0.85)';
1127:       c.lineWidth = 1.2;
1128:       c.stroke();
1129: 
1130:       const bulbs = Math.round(w / 62);
1131:       for (let i = 1; i < bulbs; i += 1) {
1132:         const t = i / bulbs;
1133:         const mt = 1 - t;
1134:         const bx = mt * mt * lightPoles[0] + 2 * mt * t * (w / 2) + t * t * lightPoles[1];
1135:         const by = mt * mt * y0 + 2 * mt * t * (y0 + sag * 2.2) + t * t * y0;
1136:         const glow = c.createRadialGradient(bx, by + 3, 0, bx, by + 3, 8);
1137:         glow.addColorStop(0, 'rgba(255, 210, 140, 0.9)');
1138:         glow.addColorStop(1, 'rgba(255, 160, 70, 0)');
1139:         c.fillStyle = glow;
1140:         c.beginPath();
1141:         c.arc(bx, by + 3, 8, 0, TAU);
1142:         c.fill();
1143:         c.fillStyle = '#ffe0a8';
1144:         c.beginPath();
1145:         c.arc(bx, by + 2, 1.4, 0, TAU);
1146:         c.fill();
1147:       }
1148:     }
1149: 
1150:     // Warm haze at the horizon line
1151:     const haze = c.createLinearGradient(0, view.horizon - 20, 0, view.farY + 20);
1152:     haze.addColorStop(0, 'rgba(255, 138, 70, 0)');
1153:     haze.addColorStop(0.6, 'rgba(255, 138, 70, 0.1)');
1154:     haze.addColorStop(1, 'rgba(255, 138, 70, 0)');
1155:     c.fillStyle = haze;
1156:     c.fillRect(0, view.horizon - 20, w, view.unit);
1157:   }
