1159:   function drawCrowd(time) {
1160:     const hype = game.hype;
1161:     for (const person of view.crowd) {
1162:       const bounce = Math.sin(time * 1.7 + person.phase) * 1.2
1163:         + (hype > 0.03 ? Math.abs(Math.sin(time * 9 + person.phase)) * hype * view.unit * 0.05 : 0);
1164:       const x = person.x;
1165:       const y = person.y - bounce;
1166:       const h = person.h;
1167: 
1168:       ctx.fillStyle = person.color;
1169:       ctx.beginPath();
1170:       ctx.ellipse(x, y - h * 0.37, h * 0.17, h * 0.2, 0, 0, TAU);
1171:       ctx.fill();
1172:       ctx.fillRect(x - h * 0.16, y - h * 0.5, h * 0.32, h * 0.42);
1173: 
1174:       ctx.fillStyle = 'rgba(20, 16, 18, 0.95)';
1175:       ctx.beginPath();
1176:       ctx.arc(x, y - h * 0.72, h * 0.14, 0, TAU);
1177:       ctx.fill();
1178: 
1179:       if (person.hasAccent) {
1180:         ctx.fillStyle = person.accent;
1181:         ctx.globalAlpha = 0.24;
1182:         ctx.fillRect(x - h * 0.15, y - h * 0.46, h * 0.3, h * 0.05);
1183:         ctx.globalAlpha = 1;
1184:       }
1185: 
1186:       if (hype > 0.25) {
1187:         ctx.strokeStyle = 'rgba(210, 220, 232, 0.55)';
1188:         ctx.lineWidth = Math.max(1.4, h * 0.06);
1189:         ctx.lineCap = 'round';
1190:         const arm = Math.sin(time * 10 + person.phase) * h * 0.14;
1191:         ctx.beginPath();
1192:         ctx.moveTo(x - h * 0.15, y - h * 0.48);
1193:         ctx.lineTo(x - h * 0.23, y - h * 0.72 + arm);
1194:         ctx.moveTo(x + h * 0.15, y - h * 0.48);
1195:         ctx.lineTo(x + h * 0.23, y - h * 0.72 - arm);
1196:         ctx.stroke();
1197:       }
1198:     }
1199:   }
